<script>
import { mapState } from "vuex";
export default {
  data() {
    return {
      couponCode: "SPRING21",
      offPrice: 40,
      showCoupon: false,
      message: {
        value: "",
        error: false,
        global: false,
      },
    };
  },
  mounted() {
    setTimeout(() => {
      if (this.isFreeTrail) {
        if (window.analytics) {
          analytics.track(
            "Coupon_popup_seen",
            {
              author: this.user && this.user.email ? this.user.email : "",
              action: "popup-opened",
            },
            {
              integrations: { Amplitude: { session_id: new Date().getTime() } },
            },
            { timestamp: new Date().getTime() }
          );
        }
        console.log("Calling tour -->>>chmln for coupon", window.chmln);
        window.location.host === "neostaging.foyr.com"
          ? window.chmln.show("611683c6c36807001cf52997")
          : window.chmln.show("61168411c36807001d4078e2");
        // if (['AU', 'CA', 'UK', 'US', 'USA', 'DE', 'GB', 'GBR', 'SG'].indexOf(this.user.ipInfo.country) > -1) {
        //     this.showCoupon = false;
        // } else {
        //     this.showCoupon = true;
        // }
      }
    }, 10000);
  },
  computed: {
    ...mapState({
      user: (state) => state.User.user,
      isFreeTrail: (state) => state.Billing.isTrial,
      isLPU: (state) => state.User.isLPU,
    }),
    locationFetch() {
      return { discount: 0, code: "" };
    },
  },
  methods: {
    copyToClipboard: function () {
      var text = document.getElementById("cpp-code").innerHTML;
      var elem = document.createElement("textarea");
      document.body.appendChild(elem);
      elem.value = text;
      elem.select();
      document.execCommand("copy");
      document.body.removeChild(elem);
      this.$root.$emit("coupon_copied");
      if (this.isFreeTrail && this.showCoupon) {
        if (window.analytics) {
          analytics.track(
            "Coupon_code_copied",
            {
              author: this.user && this.user.email ? this.user.email : "",
              action: "Click on Copy",
            },
            {
              integrations: { Amplitude: { session_id: new Date().getTime() } },
            },
            { timestamp: new Date().getTime() }
          );
        }
      }
      this.showCoupon = false;
    },
    closePopup() {
      if (this.isFreeTrail && this.showCoupon) {
        if (window.analytics) {
          analytics.track(
            "Coupon_popup-closed",
            {
              author: this.user && this.user.email ? this.user.email : "",
              action: "popup-closed",
            },
            {
              integrations: { Amplitude: { session_id: new Date().getTime() } },
            },
            { timestamp: new Date().getTime() }
          );
        }
        //  this.showCoupon = true;
      }
      this.showPopup = false;
      this.showCoupon = false;
      this.launchPaymentIframe = false;
      // this.changePlanAlert = false;
    },
  },
};
</script>

